 publication_date,accessed_date,url,catalogue_number,rights_status,source_perspective,
 access_or_reuse_restrictions,community_permission_required,translation_status,
 verification_status,notes
) VALUES
('source.egypt.late_period_temples.uee2026','Late Period Temples, version 2','PEER_REVIEWED_REFERENCE',2,'UCLA Encyclopedia of Egyptology','Christiane Zivie-Coche','lang.en','2026-06-30','2026-08-25','https://escholarship.org/content/qt70p7j5x9/qt70p7j5x9.pdf','UEE Late Period Temples v2','Copyright author; metadata, page locators and independent summary only','Peer-reviewed Egyptological synthesis','Do not reproduce the article or figures; preserve page locators',0,'English scholarly article','URL_SYNTAX_VALID','Page 16 describes the Susa statue as Egyptian workmanship made for Darius and places him under the protection of Atum-Ra, great one of Heliopolis.'),
('source.egypt.book_dead15.ucl','Book of the Dead Chapter 15: sun hymns','SCHOLARLY_DIGITAL_TEXT',2,'UCL Digital Egypt','Digital Egypt for Universities','lang.en',NULL,'2026-08-25','https://www.ucl.ac.uk/museums-static/digitalegypt/literature/religious/bd15.html','Book of the Dead chapter 15','University page and translation rights apply','Academic digital presentation of transliteration, translation and genre context','Store locators and independent summaries; do not bulk reproduce translation',0,'Egyptian transliteration with English translation','URL_SYNTAX_VALID','Explains that Chapter 15 is a modern grouping of varied sun hymns and presents Assmann Standard Hymn C-prime addressing Ra in rising as Atum Horakhty.'),
('source.iran.susa_darius.achemenet','Susa: the Statue of Darius','SCHOLARLY_PROJECT',3,'Achemenet / Musée du Louvre research network',NULL,'lang.en',NULL,'2026-08-25','https://www.achemenet.com/en/visit/?/susa/the-statue-of-darius/6=','Susa statue of Darius','Project website rights apply; metadata and independent summary only','Scholarly Achaemenid object and inscription presentation','No images packaged; retain object and inscription locators',0,'English scholarly project presentation','URL_SYNTAX_VALID','Scholarly object presentation records the Egyptian-style statue, Susa context and inscriptions in hieroglyphs and the three cuneiform languages of the empire.'),
('source.egypt.pakeshi_stela.met.90_6_30','Stela of the God''s-Father of Amun Pakeshi','MUSEUM_OBJECT',3,'The Metropolitan Museum of Art',NULL,'lang.en','ca. 721-525 BCE','2026-08-25','https://www.metmuseum.org/art/collection/search/550789','90.6.30','Object data and public-domain media follow The Met Open Access terms','Official museum object catalogue','Metadata, locator and independent summary; no image packaged',0,'English museum catalogue','URL_SYNTAX_VALID','Curatorial context distinguishes Ra-Horakhty and Atum as rising and setting solar focal gods connected with continued life; the object itself depicts Osiris and the Four Sons of Horus.' );

INSERT OR IGNORE INTO entities(
