('claim.v0120.hymn_mentions_atum_horakhty','text.egypt.sun_hymn_standard_c_prime','MENTIONED_IN','deity.egyptian.atum_horakhty',NULL,NULL,'The hymn passage addresses the rising solar deity as Atum-Horakhty.','egypt.bd15.hymn_entities','SUPPORTED',0.99,'HIGH','VERIFIED','TEXT_SAYS','TEXTUAL_WITNESS','UCL transliteration and translation','Lines 15-28 on page','Predicate direction reflects entity mention projection used by the schema.','2026-08-25T00:00:00Z'),
('claim.v0120.hymn_mentions_ra','text.egypt.sun_hymn_standard_c_prime','MENTIONED_IN','deity.egyptian.ra',NULL,NULL,'The same hymn passage directly addresses Ra in his rising.','egypt.bd15.hymn_entities','SUPPORTED',0.99,'HIGH','VERIFIED','TEXT_SAYS','TEXTUAL_WITNESS','UCL transliteration and translation','Lines 15-28 on page',NULL,'2026-08-25T00:00:00Z'),
('claim.v0120.hymn_part_chapter15','text.egypt.sun_hymn_standard_c_prime','PART_OF','text.egypt.book_dead_chapter15',NULL,NULL,'UCL presents Standard Hymn C-prime within its Book of the Dead Chapter 15 research page.','egypt.bd15.structure','SUPPORTED',0.99,'HIGH','VERIFIED','SCHOLARLY_INTERPRETATION','TEXTUAL_WITNESS','Modern scholarly organization','Current digital edition','Structural relation, not an assertion that every manuscript contains it.','2026-08-25T00:00:00Z'),
('claim.v0120.chapter15_part_book','text.egypt.book_dead_chapter15','PART_OF','text.egypt.book_dead',NULL,NULL,'Chapter 15 is a modern numbered grouping within the Book of the Dead research corpus.','egypt.bd15.structure','SUPPORTED',0.99,'HIGH','VERIFIED','SCHOLARLY_INTERPRETATION','TEXTUAL_WITNESS','Modern scholarly organization','Modern numbering since Lepsius','Does not imply one fixed ancient book sequence.','2026-08-25T00:00:00Z'),
('claim.v0120.chapter15_variants','text.egypt.book_dead_chapter15','ASSOCIATED_WITH',NULL,'multiple different sun hymns across papyri and tomb-chapel witnesses','text','UCL cautions that Chapter 15 encompasses numerous different hymns and was extended as a modern label.','egypt.bd15.variants','SUPPORTED',0.99,'HIGH','VERIFIED','SCHOLARLY_INTERPRETATION','TEXTUAL_WITNESS','Digital-edition context','New Kingdom through later witnesses','Prevents a false single-text model.','2026-08-25T00:00:00Z'),
('claim.v0120.solarforms_atum','concept.egyptian.rising_setting_solar_forms','ASSOCIATED_WITH','deity.egyptian.atum',NULL,NULL,'The Met curatorial context presents Atum as a favored setting-sun focal deity connected with continued life.','egypt.solar_forms.context','SUPPORTED',0.96,'HIGH','VERIFIED','SCHOLARLY_INTERPRETATION','SCHOLARLY_INTERPRETATION','Funerary stela curatorial context','ca. 721-525 BCE','Contextual claim; the Pakeshi stela itself does not depict Atum.','2026-08-25T00:00:00Z'),
('claim.v0120.solarforms_ra_horakhty','concept.egyptian.rising_setting_solar_forms','ASSOCIATED_WITH','deity.egyptian.ra_horakhty',NULL,NULL,'The Met curatorial context presents Ra-Horakhty as a favored rising-sun focal deity connected with continued life.','egypt.solar_forms.context','SUPPORTED',0.96,'HIGH','VERIFIED','SCHOLARLY_INTERPRETATION','SCHOLARLY_INTERPRETATION','Funerary stela curatorial context','ca. 721-525 BCE','Contextual claim; the Pakeshi stela itself does not depict Ra-Horakhty.','2026-08-25T00:00:00Z'),
('claim.v0120.pakeshi_non_depiction_guard','concept.egyptian.rising_setting_solar_forms','ASSOCIATED_WITH',NULL,'Pakeshi stela 90.6.30 depicts Osiris and the Four Sons of Horus, not Atum or Ra-Horakhty','text','The object description separates its general solar curatorial context from the figures actually depicted on the stela.','egypt.solar_forms.evidence_limit','SUPPORTED',0.99,'HIGH','VERIFIED','HISTORICAL_REALITY','ARCHAEOLOGICAL','Met object description','Object 90.6.30','Explicit guard against converting contextual commentary into a depiction edge.','2026-08-25T00:00:00Z');

INSERT OR IGNORE INTO evidence(id,claim_id,source_id,source_location,catalogue_number,evidence_type,direction,strength,research_notes)
SELECT 'evidence.'||substr(id,7),id,
 CASE WHEN id LIKE 'claim.v0120.atum_ra_%' OR id='claim.v0120.darius_protected_atum_ra' OR id IN ('claim.v0120.statue_made_egypt','claim.v0120.statue_atum_ra') THEN 'source.egypt.late_period_temples.uee2026'
      WHEN id LIKE 'claim.v0120.hymn_%' OR id LIKE 'claim.v0120.chapter15_%' OR id LIKE 'claim.v0120.atum_horakhty_%' THEN 'source.egypt.book_dead15.ucl'
      WHEN id IN ('claim.v0120.statue_represents_darius','claim.v0120.statue_found_susa','claim.v0120.statue_multilingual') THEN 'source.iran.susa_darius.achemenet'
      ELSE 'source.egypt.pakeshi_stela.met.90_6_30' END,
 CASE WHEN id LIKE 'claim.v0120.atum_ra_%' OR id='claim.v0120.darius_protected_atum_ra' OR id IN ('claim.v0120.statue_made_egypt','claim.v0120.statue_atum_ra') THEN 'UEE Late Period Temples v2, page 16'
      WHEN id LIKE 'claim.v0120.hymn_%' OR id LIKE 'claim.v0120.atum_horakhty_%' THEN 'UCL Book of the Dead 15, transliteration/translation lines 15-40'
      WHEN id LIKE 'claim.v0120.chapter15_%' THEN 'UCL Book of the Dead 15, introductory notes'
      WHEN id LIKE 'claim.v0120.statue_%' THEN 'Achemenet Susa statue presentation'
      ELSE 'Met object 90.6.30 catalogue context and object description' END,
 CASE WHEN id LIKE 'claim.v0120.solarforms_%' OR id='claim.v0120.pakeshi_non_depiction_guard' THEN '90.6.30' ELSE NULL END,
 CASE WHEN id LIKE 'claim.v0120.hymn_%' OR id LIKE 'claim.v0120.chapter15_%' OR id LIKE 'claim.v0120.atum_horakhty_%' THEN 'ANCIENT_TEXT'
      WHEN id LIKE 'claim.v0120.statue_%' OR id LIKE 'claim.v0120.solarforms_%' OR id='claim.v0120.pakeshi_non_depiction_guard' THEN 'MUSEUM_OBJECT'
      ELSE 'MODERN_SCHOLARSHIP' END,
 'SUPPORTS',confidence,'Independent summary; exact page or object locator retained.'
FROM claims WHERE id LIKE 'claim.v0120.%';

